/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field OriginalTransactionTime.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableOriginalTransactionTime extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, OriginalTransactionTime);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::UtcDateTime);

    while select OriginalTransactionTime from retailSalesTable
        group by OriginalTransactionTime
    {
        ret.add(retailSalesTable.OriginalTransactionTime);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, OriginalTransactionTime));
    qbr.value(queryValue(_value));
}
